import type { TokenTable } from "@usecredo/tokens";

/** Tailwind colour name of a role: the path with dots as hyphens (`surface.page` -> `surface-page`). */
export const colorName = (path: string) => path.replace(/\./g, "-");

/**
 * The `@theme inline` block that maps the prefixed CSS variables to Tailwind theme values.
 * Roles are exposed directly under their own names: no shadcn names, no aliases.
 */
export function buildThemeCss(table: TokenTable): string {
  const lines = [
    "/* Generated by @usecredo/tailwind-config from the token table. Do not edit. */",
    "@theme inline {",
  ];
  for (const r of table.roles) lines.push(`  --color-${colorName(r.path)}: var(${r.variable});`);
  for (const s of table.scales) {
    const [group, name] = s.path.split(".") as [string, string];
    if (group === "radius") lines.push(`  --radius-${name}: var(${s.variable});`);
    if (group === "font-family") lines.push(`  --font-${name}: var(${s.variable});`);
  }
  lines.push("}");
  return lines.join("\n") + "\n";
}

/** Candidate class names the provisional precompiled stylesheet includes. */
export function precompiledCandidates(table: TokenTable): string[] {
  const out: string[] = [];
  for (const r of table.roles) {
    const n = colorName(r.path);
    out.push(`bg-${n}`, `text-${n}`, `border-${n}`, `ring-${n}`);
  }
  for (const s of table.scales) if (s.path.startsWith("radius.")) out.push(`rounded-${s.path.split(".")[1]}`);
  return out;
}
